    f.options = () => ({api, grant: f.grant, author: 'fixture-owner', reviewerSha: reviewer.sha, reviewerDigest: reviewer.digest, now: NOW, lifetime: 3600});
    f.record = async (mutateSnapshot = () => {}, mutateRequestedSources = () => {}) => {
